def prefix(r, c, fact, invfact):
    # Sum of f(i,j) for 0<=i<=r, 0<=j<=c
    if r < 0 or c < 0:
        return 0
    return (comb(r + c + 2, r + 1, fact, invfact) - 1) % MOD

